const SETTINGS_KEY='snudifo30-settings-v2';
const localISO=dt=>`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
const todayISO=()=>localISO(new Date());
const deepClone=x=>JSON.parse(JSON.stringify(x));
function readStore(key,fallback){try{let obj=JSON.parse(localStorage.getItem(key));return obj&&typeof obj==='object'?obj:fallback;}catch{return fallback;}}
let data=deepClone(DEMO_DATA);
data.tools=[];
let settings=readStore(SETTINGS_KEY,{favorites:[],alerts:['Carte scolaire','AESH','Échéance'],seenNews:[],font:'normal'});
let ui={newsFilter:'Toutes',newsQuery:'',rightsFilter:'Tous',rightsQuery:'',calendarView:'agenda',calendarFilter:'Tous',month:localISO(new Date()).slice(0,7),supportCategory:'',supportText:'',supportName:'',supportContact:''};
const saveSettings=()=>{try{localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}catch{}};
let contentLoadFailed=false;
async function loadSharedContent(withNotice=false){
 const names=['news','events','tools'];
 const results=await Promise.allSettled(names.map(async name=>{
  const res=await fetch(`./content/${name}.json`,{cache:'no-store'});
  if(!res.ok)throw Error(`Impossible de charger ${name} (HTTP ${res.status})`);
  const records=await res.json();
  if(!Array.isArray(records)||records.length>1000||records.some(r=>!r||typeof r!=='object'||typeof r.title!=='string'||!r.title.trim()||(name!=='tools'&&typeof r.date!=='string')||(name==='tools'&&!TOOL_SECTIONS[r.section])))throw Error(`Fichier ${name} invalide`);
  return records;
 }));
 results.forEach((result,i)=>{if(result.status==='fulfilled')data[names[i]]=result.value;});
 contentLoadFailed=results.some(r=>r.status==='rejected');
 renderApp();
 if(withNotice)toast(contentLoadFailed?'Une ou plusieurs rubriques sont indisponibles ; vérifiez la connexion.':'Contenus actualisés depuis GitHub.');
 return !contentLoadFailed;
}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cleanUrl=x=>{try{let u=new URL(x);return ['http:','https:','mailto:','tel:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const frDate=s=>{if(!s)return ''; const dt=new Date(s+'T12:00:00');return isNaN(dt)?s:dt.toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});};
const weekday=s=>{let dt=new Date(s+'T12:00:00');return dt.toLocaleDateString('fr-FR',{weekday:'short'}).replace('.','');};
const daysUntil=s=>Math.round((new Date(s+'T12:00:00').getTime()-new Date(todayISO()+'T12:00:00').getTime())/86400000);
const newsSort=arr=>[...arr].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
const eventSort=arr=>[...arr].sort((a,b)=>(a.date+'T'+(a.time||'')).localeCompare(b.date+'T'+(b.time||'')));
const isPast=e=>(e.end||e.date)<todayISO();
const low=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
