const btn=(label,action,klass='btn btn-primary',extra='')=>`<button type="button" class="${klass}" data-action="${esc(action)}" ${extra}>${label}</button>`;
const ext=(url,label,klass='link-button')=>`<a class="${klass}" href="${esc(cleanUrl(url))}" target="_blank" rel="noopener noreferrer">${label} ${ico('external',15)}</a>`;
const empty=(title,detail)=>`<div class="empty">${ico('info',26)}<b>${esc(title)}</b><p>${esc(detail)}</p></div>`;
function showToast(message){let e=document.querySelector('#toast');if(!e){e=document.createElement('div');e.id='toast';document.body.append(e);} e.textContent=message;e.classList.add('visible');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>e.classList.remove('visible'),3200);}
const toast=showToast;
const navto=(page,arg)=>{location.hash='#/'+page+(arg?'?id='+encodeURIComponent(arg):'');};
function route(){let [path,q]=decodeURIComponent((location.hash||'#/accueil').replace(/^#\/?/,'')).split('?');return {page:path||'accueil',id:new URLSearchParams(q||'').get('id')||''};}
function isExternalAddress(s){return /^https?:\/\//i.test(s||'');}
function navButton(page,label,icon,active){return `<button data-action="nav" data-page="${page}" class="${active?'active':''}" aria-label="${label}">${ico(icon,21)}<span>${esc(label)}</span></button>`;}
const primaryTabs=[['accueil','Accueil','home'],['actualites','Actus','news'],['calendrier','Agenda','calendar'],['outils','Outils','tools'],['menu','Menu','menu']];
function getTab(page){if(page==='adhesion')return 'accueil';if(['droit','droits','accompagnement'].includes(page))return 'menu';if(['modele','simulateur','documents','bareme','modeles','fiches','outil-detail'].includes(page))return 'outils';if(['evenement'].includes(page))return 'calendrier';if(['news-detail'].includes(page))return 'actualites';return primaryTabs.some(x=>x[0]===page)?page:'menu';}
function appShell(body,page){let tab=getTab(page);const sidebarTabs=[...primaryTabs.slice(0,4),['droits','Mes droits','scale'],['accompagnement','Accompagnement','help'],['contact','Contact','phone'],['menu','Plus','menu']];return `<div class="layout">
<aside class="desktop-sidebar"><img class="sidebar-logo" src="./assets/logo-snudi-original.jpg" alt="Logo officiel SNUDI FO 30"/><div class="sidebar-tag">La force syndicale dans le Gard</div>${sidebarTabs.map(([p,l,i])=>`<button class="side-button ${p===page||p===tab?'active':''}" data-action="nav" data-page="${p}">${ico(i,20)} ${l}</button>`).join('')}<div class="sidebar-bottom"><b>Besoin d'un accompagnement ?</b><p>Le SNUDI-FO du Gard est à vos côtés.</p>${btn('Contacter le syndicat','nav:contact','btn btn-primary btn-sm btn-block')}</div></aside>
<div class="workspace"><header class="mobile-top"><img class="top-logo" src="./assets/logo-snudi-original.jpg" alt="SNUDI-FO 30"/><div class="top-name"><strong>SNUDI-FO 30</strong><span>Vos droits • Votre syndicat</span></div><span class="top-spacer"></span><button class="icon-btn" data-action="nav" data-page="notifications" aria-label="Notifications">${ico('bell',21)}${newsSort(data.news).some(n=>!settings.seenNews.includes(n.id))?'<i class="notification-dot"></i>':''}</button></header><main class="main">${body}<div class="footer-note">Application SNUDI-FO 30 • Vérifiez les sources et dates de mise à jour avant toute démarche.</div></main><nav class="bottom-nav" aria-label="Navigation principale">${primaryTabs.map(([p,l,i])=>navButton(p,l,i,tab===p)).join('')}</nav></div></div><div id="toast" class="toast" role="status" aria-live="polite"></div>`;}
function heading(title,desc='',back=''){return `<div class="page-heading"><div>${back?`<div class="flex-wrap" style="align-items:center;margin-bottom:8px"><button data-action="back" class="backlink" aria-label="Retour">${ico('back')}</button><span class="eyebrow">SNUDI-FO 30</span></div>`:''}<h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div></div>`;}
function titlebar(title,page){return `<div class="section-head"><h2>${esc(title)}</h2><button class="link-button" data-action="nav" data-page="${page}">Tout voir ${ico('arrow',16)}</button></div>`;}
function homeTile(title,subtitle,icon,page,highlight=false){return `<button class="tile ${highlight?'highlight':''}" data-action="nav" data-page="${page}"><span class="tile-icon">${ico(icon,23)}</span><span><strong>${esc(title)}</strong><p>${esc(subtitle)}</p></span></button>`;}
function newsCard(n){
 const cover=SnudiArticle.asPath(n.cover||'');
 const thumbnail=cover?`<img class="news-picture" src="${esc(cover)}" loading="lazy" alt="Illustration de ${esc(n.title)}">`:`<div class="news-icon">${ico(n.tag==='AESH'?'users':n.tag==='Carte scolaire'?'school':n.tag==='Formations'?'calendar':'megaphone',24)}</div>`;
 const readable=Boolean(n.bodyHtml||n.body||cover);
 return `<article class="news-card ${cover?'with-cover':''}">${thumbnail}<div class="news-card-text"><div class="news-meta">${esc(frDate(n.date))} <span class="chip red">${esc(n.tag||'Actualité')}</span></div><h3>${esc(n.title)}</h3><p>${esc(n.summary||'')}</p><div class="flex-wrap">${readable?btn(`Lire l’article ${ico('arrow',16)}`,'nav:news-detail','btn btn-outline btn-sm',`data-id="${esc(n.id)}"`):''}${n.url?ext(n.url,'Source de l’actualité'):''}</div></div></article>`;
}
function renderNewsDetail(id){
 const n=data.news.find(x=>x.id===id);if(!n)return empty('Actualité introuvable','Cette publication a peut-être été modifiée.');
 const cover=SnudiArticle.asPath(n.cover||'');
 const content=n.bodyHtml?SnudiArticle.sanitize(n.bodyHtml):`<div class="legacy-body">${esc(n.body||n.summary||'')}</div>`;
 return `${heading('Actualités','',true)}<article class="card news-detail"><span class="chip red">${esc(n.tag||'Actualité')}</span><p class="muted" style="margin-top:12px">${esc(frDate(n.date))}</p><h2 class="detail-title">${esc(n.title)}</h2><p style="font-weight:600">${esc(n.summary||'')}</p>${cover?`<img class="article-cover" src="${esc(cover)}" alt="Illustration de ${esc(n.title)}">`:''}<div class="article-content">${content}</div><div class="flex-wrap" style="margin-top:18px">${n.url?ext(n.url,'Consulter la source','btn btn-outline'):''}${btn('Toutes les actualités','nav:actualites','btn btn-neutral')}</div></article>`;
}
function eventCard(e){const d=e.date.split('-');return `<article class="card event"><div class="date-block"><span>${esc(weekday(e.date))}</span><b>${esc(d[2])}</b><span>${new Date(e.date+'T12:00:00').toLocaleDateString('fr-FR',{month:'short'})}</span></div><div class="event-info"><div class="flex-wrap" style="align-items:center;margin-bottom:6px"><span class="chip ${e.type==='Échéance'?'red':e.type==='Formation'?'yellow':'gray'}">${esc(e.type)}</span>${e.status?`<span class="badge-status ${e.status==='Confirmé'?'confirmed':''}">${esc(e.status)}</span>`:''}</div><h3>${esc(e.title)}</h3><p>${ico('pin',14)} ${esc(e.place||'Lieu non communiqué')}${e.time?` · ${esc(e.time.replace(':','h'))}`:''}${e.end&&e.end!==e.date?` · jusqu’au ${esc(frDate(e.end))}`:''}</p><div class="event-actions"><button class="small-link" data-action="ics" data-id="${esc(e.id)}">${ico('calendar',14)} Ajouter au calendrier</button>${e.source?ext(e.source,'Source','small-link'):''}</div></div></article>`;}
function tileRow(title,subtitle,icon,page){return `<button class="card rowcard clickable" data-action="nav" data-page="${page}" style="width:100%;text-align:left"><span class="row-icon">${ico(icon,21)}</span><span class="card-body"><h3>${esc(title)}</h3><p>${esc(subtitle)}</p></span>${ico('chevron',18)}</button>`;}
function renderHome(){let upcoming=eventSort(data.events).filter(e=>!isPast(e)).slice(0,3);return `<div class="stack">
<section class="hero"><div class="hero-inner"><span class="chip">${ico('spark',15)} La force syndicale dans le Gard</span><h1>Une question ?<br/>Votre syndicat est là.</h1><p>Actualités, droits, outils et accompagnement pour les professeurs des écoles, AESH et personnels du premier degré.</p><div class="hero-actions">${btn(`${ico('help',18)} J'ai besoin d'aide`,'nav:accompagnement','btn btn-yellow')}${btn(`${ico('phone',17)} Contacter FO`,'nav:contact','btn btn-white')}</div></div></section>
<section><div class="section-head"><h2>Accès rapides</h2></div><div class="grid-three">${homeTile('Actualités','Les publications du Gard','news','actualites')}${homeTile('Calendrier','Dates et échéances','calendar','calendrier',true)}${homeTile('Mes outils','Barème, courriers et fiches','tools','outils')}${homeTile('Contact','Appeler ou écrire au syndicat','mail','contact')}${homeTile("J’ai un problème",'Trouver un accompagnement','help','accompagnement')}${homeTile('Adhérer au SNUDI-FO','Pourquoi adhérer ?','users','adhesion',true)}</div></section>
<section>${titlebar('À la une','actualites')}<div class="stack">${newsSort(data.news).slice(0,2).map(newsCard).join('')||empty('Pas encore de publication','Les actualités seront publiées prochainement.')}</div></section>
<section>${titlebar('Les prochaines dates','calendrier')}<div class="stack">${upcoming.map(eventCard).join('')||empty('Pas de date à venir','Le calendrier est à actualiser.')}</div></section>
</div>`;}
function renderNews(){let categories=['Toutes',...new Set(data.news.map(x=>x.tag))];let matches=newsSort(data.news).filter(x=>(ui.newsFilter==='Toutes'||x.tag===ui.newsFilter)&&low(x.title+' '+x.summary+' '+x.tag).includes(low(ui.newsQuery)));return `${heading('Actualités','Les publications du SNUDI-FO 30, avec leur source d’origine.')}<div class="stack"><div class="notice neutral">${ico('info',18)}<span>Les contenus sont chargés depuis les publications partagées de l’application. Leur mise à jour est assurée par l’équipe syndicale.</span></div><div class="input-wrap">${ico('search',18)}<input name="newsQuery" type="search" aria-label="Rechercher une actualité" placeholder="Rechercher une actualité…" value="${esc(ui.newsQuery)}"/></div><div class="filters">${categories.map(c=>`<button data-action="news-filter" data-value="${esc(c)}" class="filter-pill ${c===ui.newsFilter?'active':''}">${esc(c)}</button>`).join('')}</div><div class="stack">${matches.map(newsCard).join('')||empty('Aucun résultat','Essayez d’autres mots ou sélectionnez une autre catégorie.')}</div>${ext(SITE,'Toutes les actualités officielles','btn btn-outline btn-block')}</div>`;}
const CALENDAR_FILTERS=['Tous','Formation','Échéance','Élections','RIS','Instance','Mobilisation','Autre'];
function renderCalendar(){
 const options=[...new Set([...CALENDAR_FILTERS,...data.events.map(e=>e.type||'Autre')])];
 const selected=ui.calendarFilter;
 const matches=e=>selected==='Tous'||(e.type||'Autre')===selected;
 const filtered=eventSort(data.events).filter(matches);
 const future=filtered.filter(e=>!isPast(e));
 const past=filtered.filter(isPast).reverse().slice(0,4);
 const selectedMonth=ui.month||localISO(new Date()).slice(0,7);
 const [yy,mm]=selectedMonth.split('-').map(Number);
 const first=new Date(yy,mm-1,1),offset=(first.getDay()+6)%7,days=new Date(yy,mm,0).getDate();
 let daycells=['L','M','M','J','V','S','D'].map(x=>`<div class="weekday">${x}</div>`).join('');
 for(let i=0;i<offset;i++)daycells+='<div></div>';
 for(let day=1;day<=days;day++){
  let iso=selectedMonth+'-'+String(day).padStart(2,'0');
  let count=filtered.filter(e=>iso>=e.date&&iso<=(e.end||e.date)).length;
  daycells+=`<button data-action="calendar-day" data-date="${iso}" class="calendar-day ${count?'evented':''} ${iso===todayISO()?'today':''}" title="${count} événement(s) le ${iso}">${day}${count?'<span class="dot"></span>':''}</button>`;
 }
 const eventsInMonth=filtered.filter(e=>e.date<=selectedMonth+'-31'&&(e.end||e.date)>=selectedMonth+'-01');
 return `${heading('Calendrier','Formations, RIS, instances, élections, mobilisations et échéances.')}<div class="stack">
 <div class="filters calendar-filters" aria-label="Filtrer les événements">${options.map(c=>`<button data-action="calendar-filter" data-value="${esc(c)}" class="filter-pill ${selected===c?'active':''}" aria-pressed="${selected===c}">${esc(c)}</button>`).join('')}</div>
 <div class="segmented"><button data-action="calendar-view" data-value="agenda" class="${ui.calendarView==='agenda'?'active':''}">Agenda</button><button data-action="calendar-view" data-value="mois" class="${ui.calendarView==='mois'?'active':''}">Mois</button></div>
 ${ui.calendarView==='agenda'?`<div class="section-head"><h2>Prochains événements</h2><span class="chip red">${future.length} à venir</span></div><div class="stack">${future.map(eventCard).join('')||empty('Aucun événement à venir','Choisissez un autre filtre ou consultez les dates passées.')}</div>${past.length?`<div class="divider"></div><h2>Événements passés</h2><div class="stack">${past.map(eventCard).join('')}</div>`:''}`:
 `<div class="card"><div class="month-title"><button data-action="month-prev" class="icon-btn" aria-label="Mois précédent">${ico('back',19)}</button><h2 style="text-transform:capitalize">${first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h2><button data-action="month-next" class="icon-btn" aria-label="Mois suivant">${ico('chevron',19)}</button></div><div class="month-grid" style="margin-top:15px">${daycells}</div><div class="subnote" style="margin-top:12px">Les jours surlignés correspondent au filtre « ${esc(selected)} ».</div></div><h2>Événements du mois</h2><div class="stack">${eventsInMonth.map(eventCard).join('')||empty('Aucune date pour ce mois','Changez de mois ou sélectionnez un autre filtre.')}</div>`}
 <div class="flex-wrap">${btn(`${ico('refresh',16)} Actualiser les dates`,'refresh-content','btn btn-outline btn-sm')}</div>
 </div>`;
}
function rightItem(r){let favorite=settings.favorites.includes(r.id);return `<div class="card rowcard"><span class="row-icon">${ico(r.icon||'scale',21)}</span><button data-action="nav" data-page="droit" data-id="${esc(r.id)}" class="card-body" style="border:0;background:none;text-align:left;cursor:pointer;padding:0"><h3>${esc(r.title)}</h3><p>${esc(r.summary)}</p></button><button class="icon-btn" data-action="favorite" data-id="${esc(r.id)}" aria-label="${favorite?'Retirer des favoris':'Ajouter aux favoris'}" style="color:${favorite?'#bd0018':'#a7a8ae'};width:35px;height:35px">${ico('star',18)}</button><button data-action="nav" data-page="droit" data-id="${esc(r.id)}" style="border:0;background:none">${ico('chevron',18)}</button></div>`;}
function renderRights(){return renderToolSection('fiches');}
function renderRight(id){return renderToolDetail(id);}
const ISSUES=[['Mouvement / mutation','map'],['Problème avec la hiérarchie','users'],['Fermeture de classe','school'],['Santé / arrêt / CLM / CITIS','heart'],['Temps partiel','clock'],['AESH','users'],['Rémunération / carrière','chart'],['Autre situation','help']];
const ISSUE_ADVICE={
 'Mouvement / mutation':'Vérifiez le calendrier et la note de service de la campagne. Conservez le barème, la liste des vœux et les justificatifs transmis.',
 'Problème avec la hiérarchie':'Rassemblez les faits et dates, les consignes écrites et les échanges. Évitez de transmettre ici des documents nominatifs concernant des élèves.',
 'Fermeture de classe':'Préparez les effectifs, niveaux, projections et conséquences sur les classes. Indiquez la date de la mesure ou du CSA concerné.',
 'Santé / arrêt / CLM / CITIS':'Exposez uniquement la difficulté administrative dans le premier courriel. Ne joignez pas automatiquement d’informations médicales confidentielles.',
 'Temps partiel':'Identifiez le motif de la demande, la quotité demandée et la date de réponse de l’administration.',
 'AESH':'Conservez contrat, quotité, emploi du temps, avenants et demandes écrites en rapport avec la difficulté.',
 'Rémunération / carrière':'Notez les périodes et éléments contestés, sans envoyer d’informations bancaires dans le premier message.',
 'Autre situation':'Décrivez les faits essentiels, les dates et l’aide souhaitée, sans données sensibles inutiles.'
};
function renderSupport(){return `${heading('Le syndicat m’accompagne','Choisissez votre situation puis préparez une demande de contact.')}<div class="stack"><div class="notice">${ico('users',21)}<span><strong>Vous rencontrez une difficulté ?</strong><br/>Le SNUDI-FO du Gard peut vous informer, vous conseiller et vous accompagner.</span></div><h2>1. Quelle difficulté rencontrez-vous ?</h2><div class="grid-two">${ISSUES.map(([name,icon])=>`<button type="button" class="support-card ${ui.supportCategory===name?'selected':''}" data-action="support-select" data-value="${esc(name)}">${ico(icon,21)}<span>${esc(name)}</span></button>`).join('')}</div>${ui.supportCategory?`<div class="card stack"><div class="flex-between"><h2>2. Préparer mon message</h2><span class="chip red">${esc(ui.supportCategory)}</span></div><div class="notice neutral">${ico('info',18)}<span>${esc(ISSUE_ADVICE[ui.supportCategory])}</span></div><form id="supportForm" class="stack"><div class="form-control"><label for="supportName">Nom ou prénom (facultatif)</label><input class="input" id="supportName" name="supportName" autocomplete="name" value="${esc(ui.supportName)}" placeholder="Comment vous appeler ?"/></div><div class="form-control"><label for="supportContact">Comment vous recontacter ? (facultatif)</label><input class="input" id="supportContact" name="supportContact" value="${esc(ui.supportContact)}" placeholder="Courriel ou téléphone"/></div><div class="form-control"><label for="supportText">Votre demande</label><textarea id="supportText" name="supportText" placeholder="Décrivez les faits utiles et précisez l’aide souhaitée…" required>${esc(ui.supportText)}</textarea><div class="field-hint">Évitez d’indiquer des données médicales détaillées ou des informations concernant des élèves.</div></div><div class="notice neutral">${ico('shield',19)}<span>Le formulaire <b>n’enregistre aucune demande sur un serveur</b> : il prépare un courriel dans votre application de messagerie. Vous déciderez de l’envoyer ou non.</span></div><button type="submit" class="btn btn-primary btn-block">${ico('mail',18)} Préparer mon courriel au syndicat</button></form></div>`:`<div class="card"><b>Comment ça fonctionne ?</b><p class="muted">Vous choisissez un thème, consultez les premiers conseils et préparez un message à envoyer directement au syndicat.</p></div>`}${btn(`${ico('phone',17)} Appeler le syndicat`,'call','btn btn-outline btn-block')}</div>`;}
function toolCard(title,subtitle,icon,page,hi=false){return homeTile(title,subtitle,icon,page,hi);}
const TOOL_SECTIONS={
 bareme:{title:'Barème mouvement',intro:'Calculateurs, règles et informations sur le mouvement.',icon:'chart'},
 modeles:{title:'Modèles de courriers',intro:'Des courriers à adapter à votre situation.',icon:'document'},
 fiches:{title:'Fiches pratiques',intro:'Informations syndicales et réglementaires à vérifier dans leur version à jour.',icon:'book'},
 documents:{title:'Documents utiles',intro:'Textes de référence, liens et ressources syndicales.',icon:'file'}
};
function toolItems(section){return data.tools.filter(r=>r.section===section);}
function toolItemCard(r){const cover=SnudiArticle.asPath(r.cover||'');return `<button class="card rowcard clickable tool-item-card" data-action="nav" data-page="outil-detail" data-id="${esc(r.id)}" style="width:100%;text-align:left">${cover?`<img class="tool-item-thumb" src="${esc(cover)}" alt="" loading="lazy">`:`<span class="row-icon">${ico(TOOL_SECTIONS[r.section]?.icon||'file',22)}</span>`}<span class="card-body"><h3>${esc(r.title)}</h3><p>${esc(r.summary||'')}</p></span>${ico('chevron',18)}</button>`;}
function renderTools(){return `${heading('Mes outils','Quatre rubriques pratiques, mises à jour par le SNUDI-FO 30.')}<div class="stack"><div class="grid-two">${toolCard('Barème mouvement','Calculer et vérifier son barème','chart','bareme',true)}${toolCard('Modèles de courriers','Consulter et copier un modèle','document','modeles')}${toolCard('Fiches pratiques','Comprendre ses droits et démarches','book','fiches')}${toolCard('Documents utiles','Textes et ressources à consulter','file','documents')}</div>${btn(`${ico('phone',18)} Contacter le SNUDI FO`,'nav:contact','btn btn-primary btn-block')}</div>`;}
function renderToolSection(section){const info=TOOL_SECTIONS[section];if(!info)return empty('Rubrique introuvable','Cette catégorie n’existe pas.');let items=toolItems(section);let controls='';
 if(section==='fiches'){
  const categories=['Tous','Favoris',...new Set(items.map(x=>x.tag||'Autre'))];
  items=items.filter(x=>(ui.rightsFilter==='Tous'||(ui.rightsFilter==='Favoris'?settings.favorites.includes(x.id):(x.tag||'Autre')===ui.rightsFilter))&&low(x.title+' '+(x.summary||'')+' '+(x.tag||'')).includes(low(ui.rightsQuery)));
  controls=`<div class="notice neutral">${ico('info',18)}<span>Les fiches sont informatives. Pour une situation particulière, vérifiez la réglementation en vigueur avec le syndicat.</span></div><div class="input-wrap">${ico('search',18)}<input type="search" name="rightsQuery" placeholder="Rechercher une fiche…" aria-label="Rechercher une fiche" value="${esc(ui.rightsQuery)}"/></div><div class="filters">${categories.map(c=>`<button data-action="rights-filter" data-value="${esc(c)}" class="filter-pill ${ui.rightsFilter===c?'active':''}">${esc(c)}</button>`).join('')}</div>`;
 }
 return `${heading(info.title,info.intro,true)}<div class="stack">${controls}${items.map(toolItemCard).join('')||empty('Aucun contenu trouvé','Modifiez les filtres ou revenez consulter cette rubrique plus tard.')}${section==='bareme'?`<h2>Échéances du mouvement</h2>${data.events.filter(e=>e.type==='Échéance').sort((a,b)=>a.date.localeCompare(b.date)).map(eventCard).join('')}`:''}${btn('Contacter le SNUDI FO','nav:contact','btn btn-outline btn-block')}</div>`;}
function renderToolDetail(id){const r=data.tools.find(x=>x.id===id);if(!r)return empty('Publication introuvable','Cette fiche a peut-être été supprimée ou modifiée.');const category=TOOL_SECTIONS[r.section]?.title||'Mes outils';const cover=SnudiArticle.asPath(r.cover||'');const body=SnudiArticle.sanitize(r.bodyHtml||'');const fav=settings.favorites.includes(r.id);
 return `${heading(category,'',true)}<div class="stack"><article class="card tool-detail"><span class="chip red">${esc(r.tag||category)}</span><h2 class="detail-title">${esc(r.title)}</h2>${r.summary?`<p class="muted">${esc(r.summary)}</p>`:''}${cover?`<img class="article-cover" src="${esc(cover)}" alt="Illustration de ${esc(r.title)}">`:''}<div class="article-content">${body}</div><div class="flex-wrap" style="margin-top:18px">${r.section==='modeles'?btn(`${ico('copy',16)} Copier le courrier`,'copy-tool','btn btn-primary',`data-id="${esc(r.id)}"`):''}${r.section==='fiches'?btn(`${ico('star',16)} ${fav?'Retirer des favoris':'Ajouter aux favoris'}`,'favorite','btn btn-neutral',`data-id="${esc(r.id)}"`):''}${r.url?ext(r.url,'Ouvrir la ressource','btn btn-outline'):''}</div></article>${btn('Retour à '+category,'nav:'+r.section,'btn btn-neutral btn-block')}${btn('Contacter le SNUDI FO','nav:contact','btn btn-outline btn-block')}</div>`;}
function renderBareme(){return renderToolSection('bareme');}
function renderTemplates(){return renderToolSection('modeles');}
function renderTemplate(id){return renderToolDetail(id);}
function renderDocuments(){return renderToolSection('documents');}
function renderDemarches(){return `${heading('Mes démarches','Une checklist simple pour préparer les pièces utiles.',true)}<div class="stack"><div class="card"><span class="chip yellow">Repères</span><h2 style="margin:12px 0">Avant de saisir l’administration</h2><div class="stack" style="gap:13px">${['Identifier précisément la demande et le service compétent.','Vérifier le texte ou la circulaire de la campagne en cours.','Repérer le délai à respecter et le mode de dépôt attendu.','Conserver une copie de la demande, des justificatifs et de la réponse.','Contacter le SNUDI-FO en cas de doute ou de refus.'].map((x,i)=>`<label style="display:flex;gap:10px;align-items:start"><input type="checkbox" data-localcheck="d${i}" ${readStore('snudi-checklist-v2',{})['d'+i]?'checked':''} style="accent-color:var(--red);width:20px;height:20px"/><span>${x}</span></label>`).join('')}</div></div><div class="card"><h2 style="margin-bottom:12px">Accès aux démarches</h2><div class="resource-list">${[['Mouvement interdépartemental 2027','bareme'],['Mes droits et autorisations','droits'],['Contacter le SNUDI-FO 30','contact'],['Modèles de courriers','modeles']].map(([t,p])=>tileRow(t,'Consulter la rubrique','arrow',p)).join('')}</div></div></div>`;}
function renderCareer(){return `${heading('Carrière et rémunération','Les références officielles avant tout calcul.',true)}<div class="stack"><div class="notice">${ico('warning',18)}<span>Un simulateur de traitement net sans grille à jour ni éléments individuels fiables risquerait d’afficher un montant faux. Il n’est pas activé dans cette version.</span></div><div class="card"><h2>Les services officiels</h2><div class="resource-list" style="margin-top:13px">${[['ENSAP — bulletins de paie et retraite','https://ensap.gouv.fr/'],['Mon espace I-Prof','https://www.education.gouv.fr/personnel/iprof.html'],['Simulateurs de la fonction publique','https://www.service-public.fr/particuliers/vosdroits/N19807']].map(([l,u])=>ext(u,l,'resource-link')).join('')}</div></div><div class="card"><h2>Besoin de vérifier un échelon, un indice ou une rémunération ?</h2><p class="muted">Contactez le syndicat en indiquant le corps, le grade, l’échelon et la nature du problème, sans envoyer de données bancaires dans le premier message.</p>${btn('Contacter le SNUDI-FO','nav:contact','btn btn-primary')}</div></div>`;}
function renderAdhesion(){
 const reasons=[
  {icon:'shield',title:'Défendre nos droits',text:'Face aux difficultés individuelles comme aux décisions collectives, nous avons besoin d’un syndicat qui informe, conseille, intervient et défend les personnels.'},
  {icon:'users',title:'Ne pas rester isolés',text:'Professeurs des écoles, AESH et autres personnels du premier degré : adhérer, c’est agir ensemble pour nos conditions de travail et pour l’École publique.'},
  {icon:'megaphone',title:'Donner du poids à nos revendications',text:'Postes, salaires, remplacement, inclusion, respect des statuts et conditions d’exercice : un syndicat plus nombreux est plus fort pour porter ces exigences.'},
  {icon:'book',title:'Faire vivre une information indépendante',text:'Communiqués, réunions d’information, formations syndicales et accompagnement : la cotisation contribue à faire vivre ce travail départemental.'}
 ];
 return `${heading('Pourquoi adhérer au SNUDI-FO 30 ?','Un syndicat plus fort, ce sont des collègues mieux organisés pour défendre leurs droits.',true)}<div class="stack">
 <section class="join-hero"><div class="join-hero-inner"><span class="chip">${ico('users',16)} La force syndicale</span><h2>Se syndiquer, c’est renforcer notre force collective.</h2><p>Dans le Gard, le SNUDI-FO défend les personnels du premier degré et porte leurs revendications. Chaque adhésion donne davantage de poids et de moyens à cette action.</p>${ext(CONTACT.adhesion,`${ico('arrow',18)} J’adhère`,'btn btn-yellow')}</div></section>
 <section class="join-section"><h2>Quatre raisons d’adhérer</h2><div class="join-reasons">${reasons.map(r=>`<article class="card join-reason"><span class="join-icon">${ico(r.icon,23)}</span><div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></div></article>`).join('')}</div></section>
 <section class="card join-independence"><span class="eyebrow">${ico('shield',16)} Indépendance syndicale</span><h2>Notre indépendance repose sur les cotisations.</h2><p>Le SNUDI-FO du Gard indique que ses ressources proviennent des cotisations de ses adhérents. Se syndiquer contribue ainsi à garantir son indépendance financière et la continuité de ses interventions.</p></section>
 <section class="join-final"><h2>Rejoignez le SNUDI-FO 30</h2><p>Vous pouvez effectuer votre adhésion sur la plateforme dédiée. Le bouton ouvre le site d’adhésion en ligne dans un nouvel onglet.</p>${ext(CONTACT.adhesion,`${ico('users',20)} J’adhère`,'btn btn-yellow btn-block')}<p class="join-privacy">L’adhésion est réalisée sur un site externe : snudifo30.web.app. Aucun renseignement d’adhésion n’est recueilli par cette application.</p></section>
 ${btn(`${ico('mail',18)} Une question avant d’adhérer ? Contacter le SNUDI-FO`,'nav:contact','btn btn-outline btn-block')}
 </div>`;
}
function renderContact(){return `${heading('Contact','L’équipe départementale du SNUDI-FO 30 à votre écoute.')}<div class="stack"><div class="card"><div class="contact-row">${ico('mail',21)}<div class="card-body"><b>Courriel</b><small>${esc(CONTACT.mail)}</small></div>${ext('mailto:'+CONTACT.mail,'Écrire')}</div><div class="contact-row">${ico('phone',21)}<div class="card-body"><b>Téléphone</b><small>${esc(CONTACT.phone)}</small></div><a class="link-button" href="tel:${CONTACT.tel}">Appeler</a></div><div class="contact-row">${ico('pin',21)}<div class="card-body"><b>Adresse</b><small>${esc(CONTACT.address)}</small></div></div><div class="contact-row">${ico('link',21)}<div class="card-body"><b>Site officiel</b><small>snudi30.force-ouvriere.org</small></div>${ext(SITE,'Ouvrir')}</div><div class="notice neutral" style="margin-top:12px">${ico('info',18)}<span>Les permanences et horaires ne sont pas renseignés : ne pas se déplacer sans confirmation préalable.</span></div></div>${ext('mailto:'+CONTACT.mail,'Écrire au SNUDI-FO 30','btn btn-primary btn-block')}<div class="grid-two">${btn(`${ico('users',19)} Adhérer`,'nav:adhesion','btn btn-yellow')}${btn(`${ico('calendar',19)} Demander un RDV`,'nav:accompagnement','btn btn-outline')}</div><div class="card"><h2>Un problème dans votre école ?</h2><p class="muted">Décrivez votre situation et préparez une demande d’accompagnement.</p>${btn('Le syndicat m’accompagne','nav:accompagnement','btn btn-neutral btn-block')}</div></div>`;}
function renderNotifications(){let unread=newsSort(data.news).filter(n=>!settings.seenNews.includes(n.id));return `${heading('Informations à suivre','Fil interne : ces informations ne sont pas des notifications push automatiques.',true)}<div class="stack"><div class="notice neutral">${ico('bell',18)}<span>Sans serveur d’envoi, l’application peut afficher des nouveautés localement, mais <b>ne peut pas notifier à distance en temps réel</b>. Les préférences ci-dessous préparent une version future.</span></div>${btn('Marquer les actualités comme lues','mark-all','btn btn-outline btn-block')}<h2>${unread.length} actualité(s) non lue(s)</h2>${unread.map(newsCard).join('')||empty('Tout est lu','Aucune nouvelle publication dans le jeu de données local.')}<div class="card"><h2>Mes thèmes prioritaires</h2><p class="muted" style="font-size:.8rem">Préférences sauvegardées seulement sur cet appareil.</p>${['Carte scolaire','AESH','Échéance','Carrière','Mobilisations','Formations'].map(t=>`<label style="display:flex;gap:12px;align-items:center;padding:9px 0"><input type="checkbox" data-alert="${esc(t)}" ${settings.alerts.includes(t)?'checked':''} style="accent-color:var(--red);width:19px;height:19px"/> ${esc(t)}</label>`).join('')}</div></div>`;}
function renderMenu(){let menuItems=[['Mes droits','Des fiches sourcées','scale','droits'],["J’ai un problème",'Un parcours d’accompagnement','help','accompagnement'],['Contact','Téléphone, adresse, courriel','phone','contact'],['Outils','Barème, courriers, fiches et documents','tools','outils'],['Adhérer au SNUDI-FO','Pourquoi adhérer ?','users','adhesion'],['Notifications','Mes préférences de suivi','bell','notifications']];return `${heading('Tous les services','Accédez aux rubriques et aux réglages.')}<div class="stack">${menuItems.map(x=>tileRow(...x)).join('')}<div class="card"><h2>Installer l’application</h2><p class="muted">Sur iPhone : ouvrez cette application dans Safari, touchez « Partager » puis « Sur l’écran d’accueil ». Sur Android : utilisez « Installer l’application » dans le menu du navigateur.</p><div class="notice neutral">${ico('laptop',17)}<span>Pour une installation complète, l’application doit être hébergée en HTTPS (par exemple sur GitHub Pages).</span></div></div><div class="card"><h2>Accessibilité</h2><div class="segmented" style="margin-top:12px"><button data-action="font" data-value="normal" class="${settings.font!=='large'?'active':''}">Texte standard</button><button data-action="font" data-value="large" class="${settings.font==='large'?'active':''}">Texte agrandi</button></div></div></div>`;}
function renderApp(){let {page,id}=route();let content;switch(page){
case 'accueil':content=renderHome();break;case 'actualites':content=renderNews();break;case 'news-detail':content=renderNewsDetail(id);break;case 'calendrier':content=renderCalendar();break;
case 'droits':content=renderRights();break;case 'droit':content=renderRight(id);break;case 'fiches':content=renderToolSection('fiches');break;case 'outil-detail':content=renderToolDetail(id);break;case 'accompagnement':content=renderSupport();break;
case 'outils':content=renderTools();break;case 'bareme':content=renderBareme();break;case 'modeles':content=renderTemplates();break;case 'modele':content=renderTemplate(id);break;
case 'demarches':content=renderTools();break;case 'carriere':content=renderTools();break;case 'documents':content=renderDocuments();break;
case 'contact':content=renderContact();break;case 'adhesion':content=renderAdhesion();break;case 'notifications':content=renderNotifications();break;
case 'menu':content=renderMenu();break;default:content=renderHome();page='accueil';}
 document.body.classList.toggle('font-large',settings.font==='large');document.getElementById('app').innerHTML=appShell(content,page);document.title=`${({accueil:'Accueil',actualites:'Actualités',calendrier:'Calendrier',droits:'Mes droits',outils:'Outils',contact:'Contact',adhesion:'Adhésion',accompagnement:'Accompagnement'})[page]||'SNUDI-FO 30'} · SNUDI-FO 30`;
}
function downloadFile(filename,body,mime){const blob=new Blob([body],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);}
function formatICal(e){let clean=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const d=s=>s.replace(/-/g,'');let start,end;
 if(e.time){let startDT=new Date(e.date+'T'+e.time+':00');let endDT=new Date(startDT.getTime()+3600000);const dt=x=>`${x.getFullYear()}${String(x.getMonth()+1).padStart(2,'0')}${String(x.getDate()).padStart(2,'0')}T${String(x.getHours()).padStart(2,'0')}${String(x.getMinutes()).padStart(2,'0')}00`;start='DTSTART:'+dt(startDT);end='DTEND:'+dt(endDT);}
 else {const next=new Date((e.end||e.date)+'T12:00:00');next.setDate(next.getDate()+1);start='DTSTART;VALUE=DATE:'+d(e.date);end='DTEND;VALUE=DATE:'+d(localISO(next));}
 return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SNUDI-FO 30//Prototype V1//FR','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+e.id+'@snudifo30.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),start,end,'SUMMARY:'+clean(e.title),'LOCATION:'+clean(e.place),'DESCRIPTION:'+clean((e.status||'')+' | '+(e.source||'')),'END:VEVENT','END:VCALENDAR'].join('\r\n');
}
function copyText(txt){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(txt).then(()=>toast('Copié dans le presse-papiers.')).catch(()=>fallbackCopy(txt));}else fallbackCopy(txt);}
function fallbackCopy(txt){let t=document.createElement('textarea');t.value=txt;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();try{document.execCommand('copy');toast('Texte copié.');}catch{toast('Copie indisponible.');}t.remove();}
function monthShift(delta){let [y,m]=ui.month.split('-').map(Number);let d=new Date(y,m-1+delta,1);ui.month=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;renderApp();}
function openMail(subject,body){let url=`mailto:${CONTACT.mail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;window.location.href=url;toast('Votre application de messagerie doit s’ouvrir. Aucun message n’a été envoyé automatiquement.');}
function handleAction(button){const action=button.dataset.action||'',id=button.dataset.id||'',value=button.dataset.value||'';
 if(action==='nav'||action.startsWith('nav:')){const page=action.startsWith('nav:')?action.split(':')[1]:button.dataset.page;navto(page,id);return;}
 if(action==='back'){if(history.length>1)history.back();else navto('menu');return;}
 if(action==='news-filter'){ui.newsFilter=value;renderApp();return;}
 if(action==='calendar-filter'){ui.calendarFilter=value;renderApp();return;}
 if(action==='refresh-content'){loadSharedContent(true);return;}
 if(action==='rights-filter'){ui.rightsFilter=value;renderApp();return;}
 if(action==='calendar-view'){ui.calendarView=value;renderApp();return;}
 if(action==='month-prev'){monthShift(-1);return;}if(action==='month-next'){monthShift(1);return;}
 if(action==='calendar-day'){let es=data.events.filter(e=>(ui.calendarFilter==='Tous'||e.type===ui.calendarFilter)&&button.dataset.date>=e.date&&button.dataset.date<=(e.end||e.date));toast(es.length?es.map(x=>x.title).join(' • '):'Aucun événement ce jour-là.');return;}
 if(action==='ics'){let e=data.events.find(x=>x.id===id);if(e){downloadFile('SNUDI-FO-30-'+e.date+'.ics',formatICal(e),'text/calendar;charset=utf-8');toast('Événement téléchargé au format calendrier (.ics).');}return;}
 if(action==='favorite'||action.startsWith('favorite:')){let rid=id||action.split(':')[1];settings.favorites=settings.favorites.includes(rid)?settings.favorites.filter(x=>x!==rid):[...settings.favorites,rid];saveSettings();renderApp();return;}
 if(action==='copylink'){copyText(location.href);return;}
 if(action==='copy-tool'){const item=data.tools.find(x=>x.id===id);if(!item)return;const tmp=document.createElement('div');tmp.innerHTML=SnudiArticle.sanitize(item.bodyHtml||'');copyText(item.copyText||tmp.innerText||tmp.textContent||'');return;}
 if(action==='support-select'){ui.supportCategory=value;renderApp();return;}
 if(action==='support-school'){ui.supportCategory='Fermeture de classe';navto('accompagnement');return;}
 if(action==='call'){window.location.href='tel:'+CONTACT.tel;return;}
 if(action==='copy-template'||action==='mail-template'){let t=data.templates.find(x=>x.id===(id||action.split(':')[1]));if(!t)return;if(action==='copy-template')copyText(t.body);else openMail(t.title,t.body);return;}
 if(action==='mark-all'){settings.seenNews=data.news.map(x=>x.id);saveSettings();renderApp();return;}
 if(action==='font'){settings.font=value;saveSettings();renderApp();return;}

}
function onInput(e){let n=e.target.name;
 if(['newsQuery','rightsQuery','schoolQuery'].includes(n)){let pos=e.target.selectionStart;ui[n]=e.target.value;renderApp();let next=document.querySelector('[name="'+n+'"]');if(next){next.focus();try{next.setSelectionRange(pos,pos);}catch{}}return;}
 if(['supportName','supportContact','supportText'].includes(n))ui[n]=e.target.value;
}
function onSubmit(e){if(e.target.id==='supportForm'){e.preventDefault();const fd=new FormData(e.target);ui.supportName=String(fd.get('supportName')||'').trim();ui.supportContact=String(fd.get('supportContact')||'').trim();ui.supportText=String(fd.get('supportText')||'').trim();if(!ui.supportText){toast('Précisez votre demande.');return;}let body=`Bonjour,\n\nJe vous contacte concernant : ${ui.supportCategory}\n\n${ui.supportText}\n\n${ui.supportName?'Nom / prénom : '+ui.supportName+'\n':''}${ui.supportContact?'Me recontacter : '+ui.supportContact+'\n':''}\nCordialement.`;openMail('Demande d’accompagnement — '+ui.supportCategory,body);return;}

}
async function onChange(e){if(e.target.dataset.alert){const tag=e.target.dataset.alert;settings.alerts=e.target.checked?[...new Set([...settings.alerts,tag])]:settings.alerts.filter(x=>x!==tag);saveSettings();return;}
 if(e.target.dataset.localcheck){const key=e.target.dataset.localcheck;let m=readStore('snudi-checklist-v2',{});m[key]=e.target.checked;try{localStorage.setItem('snudi-checklist-v2',JSON.stringify(m));}catch{}return;}

}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)handleAction(b);});
document.addEventListener('input',onInput);
document.addEventListener('submit',onSubmit);
document.addEventListener('change',onChange);
window.addEventListener('hashchange',()=>{renderApp();window.scrollTo({top:0,behavior:'auto'});});
if(!location.hash)location.hash='#/accueil';
renderApp();
if(location.protocol==='http:'||location.protocol==='https:')loadSharedContent();
if('serviceWorker' in navigator && location.protocol.startsWith('http')){window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>{});});}
